// Extrae la ficha JSON de la respuesta del modelo sin fiarse de que venga limpia.
const salida = [];
for (const item of $input.all()) {
  const peticion = $('Filtrar vacias').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let ficha;
  try {
    ficha = JSON.parse(bruto);
  } catch (error) {
    ficha = { pagina: null, tipo: 'texto', resumen: 'ficha no parseable', criterio_hecho: '', preguntas: ['revisar a mano: ' + bruto.slice(0, 150)], completa: false, motivo: 'respuesta no parseable' };
  }
  salida.push({
    json: {
      ...peticion,
      pagina: ficha.pagina ?? null,
      tipo: ficha.tipo ?? 'texto',
      resumen: ficha.resumen ?? '',
      criterio_hecho: ficha.criterio_hecho ?? '',
      preguntas: (ficha.preguntas ?? []).join(' | '),
      completa: Boolean(ficha.completa),
      motivo: ficha.motivo ?? '',
      ficha_tecnica: JSON.stringify(ficha),
    },
  });
}
return salida;

